export const BASE_DIALOGUE_LENGTHS_V9 = {"intro": 7, "ratAccept": 5, "ratDone": 10, "aside": 6, "contract": 20, "sisterIdle": 7, "clerkIdle": 5, "courierAccept": 5, "herbWoman": 9, "watch": 6, "ambient_clerk_chapterComplete": 5, "ambient_watch_chapterComplete": 5, "ambient_dolly_beforeAssassination": 5, "ambient_oldwoman_chapterComplete": 4, "lanternWatchAfter": 5, "lanternReturnAfter": 6, "lanternAfterHelp": 4, "womanMedicineReceived": 5, "ratProgressTalk": 4, "letterProgressTalk": 4, "herbHintTalk": 4, "sisterBeforeDeparture": 10, "sisterAfterBell": 10, "sisterAfterEscape": 12, "lottieGreeting": 7, "lottieFoundFirst": 7, "lottieResetReady": 9, "lottieIdle": 7, "farewellSteward": 8, "farewellSister": 13, "farewellDolly": 8, "farewellDollyUnfinished": 6, "farewellLottie": 9, "farewellLottieUnfinished": 7, "selineWorkProgress": 3, "selineWorkDone": 7, "selineIdleBefore": 7, "selineIdleAfter": 6, "ch1SisterBoots": 7, "ch1LottieLedger": 7, "selineRewardMedicine": 3, "selineFoundFirst": 7, "saintBrief": 13, "assassination": 18, "canalStart": 9, "chapterEnd": 14, "hostile": 3, "saintSealEarly": 6, "saintSealTalk": 7, "saintRoadEarly": 6, "saintRoadTalk": 7, "saintGateWarning": 3, "saintWaitHostile": 3, "saintGuestroom": 3, "saintWorkshop": 4, "saintFarewellWait": 5, "saintCave": 3, "ch2Arrival": 8, "ch2Relay": 12, "ch2Terms": 11, "ch2Bridge": 9, "ch2OuterCourt": 8, "ch2TargetBefore": 4, "ch2InnerDoor": 10, "ch2Alarm": 8, "ch2Breakout": 8, "ch2TargetAfter": 5, "ch2Spillway": 10, "ch2ExileApproach": 10, "ch2ExileEnd": 9, "saintPostIdle": 5, "saintInnIdle": 5, "saintEscapeOnly": 3, "saintAlarmOnly": 3, "saintGateOnly": 3};
export function applyDialogueQualityV9(dialogues) {
  for (const [id, entries] of Object.entries(DIALOGUE_PATCHES_V9)) {
    if (!Array.isArray(dialogues[id])) throw new Error('V9 missing dialogue: '+id);
    if (dialogues[id].length !== BASE_DIALOGUE_LENGTHS_V9[id]) throw new Error('V9 staging index changed: '+id);
    for (const [index, row] of Object.entries(entries)) {
      const target=dialogues[id][Number(index)];
      target[0]=row[0]; target[1]=row[1];
    }
  }
  for(const [id, lines] of Object.entries(NEW_NARRATIVE_DIALOGUES_V9)) dialogues[id]=lines.map(row=>[...row]);
  for (const lines of Object.values(dialogues)) if(Array.isArray(lines)) for(const row of lines) {
    if(typeof row?.[0] === 'string') row[0]=row[0].replaceAll('维兰','诺恩');
    if(typeof row?.[1] === 'string') row[1]=row[1].replaceAll('维兰','诺恩');
  }
  return dialogues;
}
